package io.github.diodeme.ji.session.model;

import java.time.Instant;
import java.util.List;
import java.util.Objects;
import java.util.Optional;

/** Canonical lifecycle projection for one Agent Session. */
public record CanonicalSessionState(
        SessionId sessionId,
        LifecycleStatus status,
        long revision,
        Optional<Run> activeRun,
        List<Run> completedRuns) {

    public CanonicalSessionState {
        Objects.requireNonNull(sessionId, "sessionId");
        Objects.requireNonNull(status, "status");
        Objects.requireNonNull(activeRun, "activeRun");
        completedRuns = List.copyOf(completedRuns);
        if (revision < 0) {
            throw new IllegalArgumentException("revision must be non-negative");
        }
        boolean mayOwnUnfinishedRun = status == LifecycleStatus.ACTIVE
                || status == LifecycleStatus.PAUSED
                || status == LifecycleStatus.CANCELLING;
        if (status == LifecycleStatus.ACTIVE && activeRun.isEmpty()) {
            throw new IllegalArgumentException("an active session must own exactly one active run");
        }
        if (!mayOwnUnfinishedRun && activeRun.isPresent()) {
            throw new IllegalArgumentException("only an active, paused, or cancelling session may own an unfinished run");
        }
        if (activeRun.isPresent() && activeRun.orElseThrow().status() == LifecycleStatus.TERMINAL) {
            throw new IllegalArgumentException("activeRun must be unfinished");
        }
        if (completedRuns.stream().anyMatch(run -> run.status() != LifecycleStatus.TERMINAL)) {
            throw new IllegalArgumentException("completedRuns must contain only terminal runs");
        }
    }

    public record SessionId(String value) {
        public SessionId {
            requireId(value, "sessionId");
        }
    }

    public record RunId(String value) {
        public RunId {
            requireId(value, "runId");
        }
    }

    public record TurnId(String value) {
        public TurnId {
            requireId(value, "turnId");
        }
    }

    public record AttemptId(String value) {
        public AttemptId {
            requireId(value, "attemptId");
        }
    }

    public record ToolExecutionId(String value) {
        public ToolExecutionId {
            requireId(value, "toolExecutionId");
        }
    }

    public record PermissionId(String value) {
        public PermissionId {
            requireId(value, "permissionId");
        }
    }

    public record CompactionId(String value) {
        public CompactionId {
            requireId(value, "compactionId");
        }
    }

    public record Run(
            RunId id,
            LifecycleStatus status,
            Optional<Outcome> outcome,
            List<Turn> turns,
            Instant startedAt,
            Optional<Instant> endedAt) {
        public Run {
            Objects.requireNonNull(id, "id");
            Objects.requireNonNull(status, "status");
            Objects.requireNonNull(outcome, "outcome");
            turns = List.copyOf(turns);
            Objects.requireNonNull(startedAt, "startedAt");
            Objects.requireNonNull(endedAt, "endedAt");
            requireTerminalConsistency(status, outcome, endedAt, "run");
        }
    }

    public record Turn(
            TurnId id,
            LifecycleStatus status,
            Optional<Outcome> outcome,
            List<Attempt> attempts,
            List<ToolExecution> tools,
            List<Permission> permissions,
            List<Compaction> compactions) {
        public Turn {
            Objects.requireNonNull(id, "id");
            Objects.requireNonNull(status, "status");
            Objects.requireNonNull(outcome, "outcome");
            attempts = List.copyOf(attempts);
            tools = List.copyOf(tools);
            permissions = List.copyOf(permissions);
            compactions = List.copyOf(compactions);
            requireTerminalConsistency(status, outcome, "turn");
            if (attempts.isEmpty()) {
                throw new IllegalArgumentException("a turn must contain at least one attempt");
            }
            var attemptIds = new java.util.HashSet<AttemptId>();
            var resultEntryIds = new java.util.HashSet<String>();
            for (int index = 0; index < attempts.size(); index++) {
                Attempt attempt = attempts.get(index);
                if (attempt.number() != index + 1) {
                    throw new IllegalArgumentException("attempt numbers must be contiguous and one-based");
                }
                if (!attemptIds.add(attempt.id()) || !resultEntryIds.add(attempt.resultEntryId())) {
                    throw new IllegalArgumentException("attempt and result entry identities must be unique within a turn");
                }
            }
        }
    }

    public record Attempt(
            AttemptId id,
            int number,
            AttemptStep step,
            LifecycleStatus status,
            Optional<Outcome> outcome,
            String resultEntryId) {
        public Attempt {
            Objects.requireNonNull(id, "id");
            if (number < 1) {
                throw new IllegalArgumentException("attempt number must be positive");
            }
            Objects.requireNonNull(step, "step");
            Objects.requireNonNull(status, "status");
            Objects.requireNonNull(outcome, "outcome");
            requireTerminalConsistency(status, outcome, "attempt");
            requireId(resultEntryId, "resultEntryId");
        }
    }

    public record ToolExecution(
            ToolExecutionId id,
            String toolCallId,
            String toolName,
            ToolRetryContract retryContract,
            LifecycleStatus status,
            Optional<Outcome> outcome) {
        public ToolExecution {
            Objects.requireNonNull(id, "id");
            requireId(toolCallId, "toolCallId");
            requireId(toolName, "toolName");
            retryContract = retryContract == null ? ToolRetryContract.NON_RETRYABLE : retryContract;
            Objects.requireNonNull(status, "status");
            Objects.requireNonNull(outcome, "outcome");
            requireTerminalConsistency(status, outcome, "tool execution");
        }
    }

    public record Permission(
            PermissionId id,
            ToolExecutionId toolExecutionId,
            LifecycleStatus status,
            Optional<Outcome> outcome,
            Instant expiresAt) {
        public Permission {
            Objects.requireNonNull(id, "id");
            Objects.requireNonNull(toolExecutionId, "toolExecutionId");
            Objects.requireNonNull(status, "status");
            Objects.requireNonNull(outcome, "outcome");
            requireTerminalConsistency(status, outcome, "permission");
            Objects.requireNonNull(expiresAt, "expiresAt");
        }
    }

    public record Compaction(
            CompactionId id,
            LifecycleStatus status,
            Optional<Outcome> outcome,
            String resultEntryId) {
        public Compaction {
            Objects.requireNonNull(id, "id");
            Objects.requireNonNull(status, "status");
            Objects.requireNonNull(outcome, "outcome");
            requireTerminalConsistency(status, outcome, "compaction");
            requireId(resultEntryId, "resultEntryId");
        }
    }

    public enum LifecycleStatus {
        PENDING,
        ACTIVE,
        PAUSED,
        CANCELLING,
        TERMINAL
    }

    public enum Outcome {
        COMPLETED,
        ABORTED,
        FAILED,
        DENIED,
        EXPIRED
    }

    public enum AttemptStep {
        ASSISTANT,
        TOOL,
        COMPACTION,
        BRANCH_SUMMARY
    }

    public enum ToolRetryContract {
        READ_ONLY,
        IDEMPOTENT,
        RESUMABLE,
        NON_RETRYABLE
    }

    private static void requireId(String value, String name) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(name + " must not be blank");
        }
    }

    private static void requireTerminalConsistency(
            LifecycleStatus status,
            Optional<Outcome> outcome,
            Optional<Instant> endedAt,
            String aggregate) {
        requireTerminalConsistency(status, outcome, aggregate);
        if (status == LifecycleStatus.TERMINAL && endedAt.isEmpty()) {
            throw new IllegalArgumentException(aggregate + " terminal status requires end time");
        }
        if (status != LifecycleStatus.TERMINAL && endedAt.isPresent()) {
            throw new IllegalArgumentException(aggregate + " non-terminal status cannot have end time");
        }
    }

    private static void requireTerminalConsistency(
            LifecycleStatus status,
            Optional<Outcome> outcome,
            String aggregate) {
        if (status == LifecycleStatus.TERMINAL && outcome.isEmpty()) {
            throw new IllegalArgumentException(aggregate + " terminal status requires outcome");
        }
        if (status != LifecycleStatus.TERMINAL && outcome.isPresent()) {
            throw new IllegalArgumentException(aggregate + " non-terminal status cannot have outcome");
        }
    }
}

